CREATE TABLE IF NOT EXISTS roles (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, last_name TEXT NOT NULL, first_name TEXT NOT NULL, middle_name TEXT, login TEXT NOT NULL UNIQUE, role_id INTEGER REFERENCES roles(id));
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY, category TEXT NOT NULL, subcategory TEXT, name TEXT NOT NULL, manufacturer TEXT, image_path TEXT, description TEXT, composition TEXT, price NUMERIC NOT NULL);
CREATE TABLE IF NOT EXISTS sizes (id INTEGER PRIMARY KEY, value TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS stock_items (id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), size_id INTEGER NOT NULL REFERENCES sizes(id), quantity_available INTEGER NOT NULL DEFAULT 0 CHECK(quantity_available >= 0), UNIQUE(product_id, size_id));
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY, order_date DATE NOT NULL, user_id INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id INTEGER NOT NULL REFERENCES products(id), size_id INTEGER NOT NULL REFERENCES sizes(id), quantity INTEGER NOT NULL CHECK(quantity > 0), price NUMERIC NOT NULL);
